mapper.select:
select
  id, is_deleted, nezha_tenant_code, name, description, status,
  trace_id, agent_id, task_description, tool_calls, duration, result, error_msg,
  trace_type, trace_status, definition_id, registry_id, publish_record_id, start_at, end_at,
  create_at, create_by, create_name, update_at, update_by, update_name
from agent_trace
where is_deleted = 0

  and name like concat('%', #{name,jdbcType=VARCHAR}, '%')


  and status = #{status,jdbcType=VARCHAR}


  and agent_id = #{agentId,jdbcType=VARCHAR}


  and trace_type = #{traceType,jdbcType=VARCHAR}


  and trace_status = #{traceStatus,jdbcType=VARCHAR}


  and definition_id = #{definitionId,jdbcType=BIGINT}

order by id desc
